  await figma.loadFontAsync({family:'Poppins',style:st});
  const s = figma.createTextStyle(); s.name='Run&Earn / '+n;
  s.fontSize=sz; s.fontName={family:'Poppins',style:st}; s.lineHeight={unit:'PIXELS',value:lh};
}
log.push('text styles: '+TS.length);

async function T(chars,o={}){
  const {size=14,style='Regular',color=C.text,align='LEFT',ls=0,lh=null,w=null,name=null}=o;
  const fn={family:'Poppins',style};
  await figma.loadFontAsync(fn);
  const t=figma.createText(); t.fontName=fn; t.characters=chars; t.fontSize=size;
  t.fills=P(color); t.textAlignHorizontal=align;
  if(ls) t.letterSpacing={unit:'PERCENT',value:ls};
  if(lh) t.lineHeight={unit:'PIXELS',value:lh};
  if(w){t.textAutoResize='HEIGHT';t.resize(w,t.height);}
  if(name) t.name=name;
  return t;
}
function F(name,o={}){
  const f=figma.createFrame(); f.name=name;
  f.layoutMode=o.lm||'NONE';
  if(o.lm){f.primaryAxisSizingMode=o.pw==='fix'?'FIXED':'AUTO';f.counterAxisSizingMode=o.ph==='fix'?'FIXED':'AUTO';
    f.itemSpacing=o.gap||0;f.paddingTop=o.pt||0;f.paddingBottom=o.pb||0;f.paddingLeft=o.pl||0;f.paddingRight=o.pr||0;
    f.primaryAxisAlignItems=o.jc||'MIN';f.counterAxisAlignItems=o.ac||'MIN';}
  f.fills=o.fill?P(o.fill,o.fo):[];
  if(o.r!==undefined)f.cornerRadius=o.r;
  if(o.stroke){f.strokes=P(o.stroke);f.strokeWeight=o.sw||1;f.strokeAlign='INSIDE';}
  if(o.w&&o.h)f.resize(o.w,o.h);
  f.clipsContent=o.clip===undefined?false:o.clip;
  return f;
}
async function IC(id,o={}){
  const src=await figma.getNodeByIdAsync(id);
  const inst=src.createInstance();
  const size=o.size||Math.max(src.width,src.height);
  const k=size/Math.max(src.width,src.height);
  if(Math.abs(k-1)>0.001) inst.rescale(k);
  if(o.color){
    const nodes = inst.type==='VECTOR'?[inst]:inst.findAll(n=>true);
    for(const n of nodes){
      try{ const f=n.fills; if(Array.isArray(f)&&f.length&&f.every(x=>x.type==='SOLID')) n.fills=P(o.color); }catch(e){}
      try{ const s=n.strokes; if(Array.isArray(s)&&s.length&&s.every(x=>x.type==='SOLID')) n.strokes=P(o.color); }catch(e){}
    }
  }
  inst.name=o.name||src.name;
  return inst;
}
