function F(name,o={}){
  const f=figma.createFrame();f.name=name;
  const lm=o.lm||'NONE';f.layoutMode=lm;
  if(lm!=='NONE'){
    const vert=(lm==='VERTICAL');
    f.primaryAxisSizingMode=(vert? o.h!==undefined : o.w!==undefined)?'FIXED':'AUTO';
    f.counterAxisSizingMode=(vert? o.w!==undefined : o.h!==undefined)?'FIXED':'AUTO';
