function rgb(h){h=h.replace('#','');return{r:parseInt(h.slice(0,2),16)/255,g:parseInt(h.slice(2,4),16)/255,b:parseInt(h.slice(4,6),16)/255};}
function P(h,o){return[{type:'SOLID',color:rgb(h),opacity:o===undefined?1:o}];}
function G(c1,c2,ang){return[{type:'GRADIENT_LINEAR',gradientTransform:[[Math.cos(ang),Math.sin(ang),0],[-Math.sin(ang),Math.cos(ang),0.5]],gradientStops:[{position:0,color:{...rgb(c1),a:1}},{position:1,color:{...rgb(c2),a:1}}]}];}
async function T(chars,o={}){
  const{size=14,style='Regular',color=C.text,align='LEFT',ls=0,lh=null,w=null,name=null}=o;
  const fn={family:'Poppins',style};await figma.loadFontAsync(fn);
  const t=figma.createText();t.fontName=fn;t.characters=chars;t.fontSize=size;t.fills=P(color);t.textAlignHorizontal=align;
  if(ls)t.letterSpacing={unit:'PERCENT',value:ls};
  if(lh)t.lineHeight={unit:'PIXELS',value:lh};
  if(w){t.textAutoResize='HEIGHT';t.resize(w,t.height);}
  if(name)t.name=name;
