function F(name,o={}){
  const f=figma.createFrame();f.name=name;
  const lm=o.lm||'NONE';f.layoutMode=lm;
  if(lm!=='NONE'){
    const vert=(lm==='VERTICAL');
    f.primaryAxisSizingMode=(vert? o.h!==undefined : o.w!==undefined)?'FIXED':'AUTO';
    f.counterAxisSizingMode=(vert? o.w!==undefined : o.h!==undefined)?'FIXED':'AUTO';
    f.itemSpacing=o.gap||0;
    f.paddingTop=o.pt||0;f.paddingBottom=o.pb||0;f.paddingLeft=o.pl||0;f.paddingRight=o.pr||0;
    f.primaryAxisAlignItems=o.jc||'MIN';f.counterAxisAlignItems=o.ac||'MIN';
  }
  f.fills=o.fill?P(o.fill,o.fo):(o.gradient||[]);
  if(o.r!==undefined)f.cornerRadius=o.r;
  if(o.stroke){f.strokes=P(o.stroke);f.strokeWeight=o.sw||1;f.strokeAlign='INSIDE';}
  if(o.w!==undefined&&o.h!==undefined)f.resize(o.w,o.h);
