const out=[];
for(const id of ['1:24','1:26','1:31','1:41']){
  const n=await figma.getNodeByIdAsync(id);
  out.push('== '+n.name+' '+id+' ['+Math.round(n.width)+'x'+Math.round(n.height)+'] main='+(n.mainComponent?n.mainComponent.id+' "'+n.mainComponent.name+'"':'-'));
  function w(x,d){
    let s='  '.repeat(d)+x.type+' "'+x.name+'" ['+Math.round(x.width)+'x'+Math.round(x.height)+'] @'+Math.round(x.x)+','+Math.round(x.y);
    if(x.type==='TEXT'){s+=' chars="'+x.characters+'" size='+x.fontSize+' style='+x.fontName.style;}
    try{if(Array.isArray(x.fills)&&x.fills.length)s+=' fills='+JSON.stringify(x.fills).slice(0,160);}catch(e){}
    try{if(x.cornerRadius!==undefined&&x.cornerRadius!==0&&x.cornerRadius!==figma.mixed)s+=' r='+x.cornerRadius;}catch(e){}
    try{if(x.layoutMode&&x.layoutMode!=='NONE')s+=' lm='+x.layoutMode+' gap='+x.itemSpacing+' pad='+x.paddingTop+'/'+x.paddingRight+'/'+x.paddingBottom+'/'+x.paddingLeft+' jc='+x.primaryAxisAlignItems+' ac='+x.counterAxisAlignItems+' pSize='+x.primaryAxisSizingMode+' cSize='+x.counterAxisSizingMode;}catch(e){}
    out.push(s);
    if('children' in x)for(const c of x.children)w(c,d+1);
  }
  w(n,0);
}
